window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[197]={"id":"197","numero":197,"titre":"Spondylarthrite inflammatoire","objectifs":[{"id":"197-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la description des spondyloarthrites","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">spondyloarthrites</span></strong> (SpA, anciennement spondylarthropathies) regroupent des <span class=\"kw-def\">rhumatismes inflammatoires chroniques</span> qui partagent certaines de leurs <span class=\"kw-clinique\">manifestations cliniques</span> ainsi qu'un <span class=\"kw-etio\">terrain génétique commun</span> (gène <span class=\"kw-bio\">HLA-B27</span>).</p>\n\n      <h4 class=\"obj-sub\"><span class=\"kw-clinique\">Les</span> entités regroupées sous le terme « spondyloarthrites »</h4>\n      <ul>\n        <li><span class=\"kw-def\">Spondyloarthrite ankylosante</span> (= SpA axiale radiographique)</li>\n        <li><span class=\"kw-def\">Rhumatisme psoriasique</span></li>\n        <li><span class=\"kw-def\">Arthrites réactionnelles</span></li>\n        <li><span class=\"kw-def\">Arthrites associées aux entérocolopathies inflammatoires</span> (<span class=\"kw-clinique\">MICI</span>)</li>\n        <li><span class=\"kw-def\">Formes juvéniles</span></li>\n        <li><span class=\"kw-def\">SpA indifférenciées</span></li>\n        <li><span class=\"kw-def\">Syndrome SAPHO</span> (inclus selon certains) : <span class=\"kw-clinique\">synovite</span>, <span class=\"kw-clinique\">acné</span>, <span class=\"kw-clinique\">pustulose</span>, <span class=\"kw-clinique\">hyperostose</span>, <span class=\"kw-clinique\">ostéite</span></li>\n      </ul>\n\n      <h4 class=\"obj-sub\"><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>rands syndromes (combinés de façon variable)</h4>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Traduction</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pelvi-rachidien / axial</strong></td><td>Atteinte <span class=\"kw-clinique\">rachidienne</span> + <span class=\"kw-imagerie\">sacro-iliite</span></td></tr>\n          <tr><td><strong>Enthésopathique</strong></td><td><span class=\"kw-clinique\">Enthésites</span> axiales ou périphériques</td></tr>\n          <tr><td><strong>Articulaire périphérique</strong></td><td><span class=\"kw-clinique\">Oligoarthrite</span> + <span class=\"kw-clinique\">enthésites</span> périphériques</td></tr>\n          <tr><td><strong>Extra-articulaire</strong></td><td><span class=\"kw-clinique\">Uvéite</span> ; <span class=\"kw-etio\">psoriasis</span> ; <span class=\"kw-etio\">MICI</span> ; plus rarement atteinte cardiaque (<span class=\"kw-clinique\">trouble de conduction</span>, <span class=\"kw-clinique\">insuffisance aortique</span>) ; infection urogénitale/digestive (arthrite réactionnelle)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Nouvelle terminologie (phénotype clinico-radiologique)</h4>\n      <table >\n        <thead><tr><th>Phénotype</th><th>Sous-types</th></tr></thead>\n        <tbody>\n          <tr><td><strong>SpA axiales</strong></td><td><strong>Radiographiques</strong> (= spondyloarthrite ankylosante) : avec <span class=\"kw-imagerie\">sacro-iliite radiographique</span><br><strong>Non radiographiques</strong> : sans sacro-iliite radiographique</td></tr>\n          <tr><td><strong>SpA périphériques articulaires</strong></td><td><span class=\"kw-imagerie\">Érosives</span> ou non érosives</td></tr>\n          <tr><td><strong>SpA enthésiques</strong></td><td>Spondyloarthrites périphériques enthésiques</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> manifestations extra-articulaires concomitantes peuvent être ajoutées pour caractériser le phénotype (ex. <em>SpA axiale non radiographique avec uvéite antérieure</em>, <em>SpA périphérique articulaire non érosive avec <span class=\"kw-clinique\">psoriasis</span></em>).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0},{"id":"197-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie","contenu":"<table >\n        <thead><tr><th>Paramètre</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-def\">Prévalence</span> globale de l'ensemble des spondyloarthrites : <span class=\"kw-chiffre\">0,35 %</span> en France</td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>Prédominance masculine (<span class=\"kw-chiffre\">1,5 H / 1 F</span>) ; <span class=\"kw-clinique\">les</span> femmes sont aussi fréquemment atteintes mais avec des <span class=\"kw-clinique\">formes moins sévères</span></td></tr>\n          <tr><td><strong>Âge</strong></td><td>Début chez l'adulte jeune dans la majorité des cas (<span class=\"kw-chiffre\">&lt; 35 ans</span>) ; âge moyen de début des symptômes : <span class=\"kw-chiffre\">26 ans</span> (souvent un <span class=\"kw-alerte\">délai diagnostique de plusieurs années</span>)</td></tr>\n          <tr><td><strong>Agrégation familiale</strong></td><td>Chez <span class=\"kw-chiffre\">20 à 30 %</span> des SpA, avec coségrégation des manifestations (<span class=\"kw-etio\">spondyloarthrite</span>, <span class=\"kw-etio\">uvéite</span>, <span class=\"kw-etio\">entérocolopathie</span>, <span class=\"kw-etio\">psoriasis</span>) → facteurs de prédisposition communs</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Portage du <span class=\"kw-bio\">HLA-B27</span> selon la situation</h4>\n      <table >\n        <thead><tr><th>Population</th><th>Portage</th></tr></thead>\n        <tbody>\n          <tr><td>Population générale caucasienne</td><td><span class=\"kw-chiffre\">6-8 %</span></td></tr>\n          <tr><td>Sujets à peau noire</td><td><span class=\"kw-chiffre\">Exceptionnel</span> (sa présence a alors une valeur diagnostique encore plus élevée)</td></tr>\n          <tr><td>SpA ankylosante</td><td><span class=\"kw-chiffre\">&gt; 90 %</span> (association très forte, <span class=\"kw-chiffre\">RR &gt; 200</span>)</td></tr>\n          <tr><td>Arthrite réactionnelle</td><td><span class=\"kw-chiffre\">65 à 75 %</span></td></tr>\n          <tr><td>Rhumatisme psoriasique / arthrites des entérocolopathies</td><td><span class=\"kw-chiffre\">50-70 %</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"197-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le rôle du terrain génétique : le gène HLA-B27","contenu":"<p>Le <strong><span class=\"kw-bio\">HLA-B27</span></strong> est un <span class=\"kw-def\">allèle normal du CMH de classe I</span>. C'est le principal <span class=\"kw-etio\">facteur de prédisposition génétique</span> des spondyloarthrites, mais il n'est <span class=\"kw-clinique\">ni nécessaire ni suffisant</span>.</p>\n\n      <table >\n        <thead><tr><th>Situation</th><th>Portage du <span class=\"kw-bio\">HLA-B27</span></th></tr></thead>\n        <tbody>\n          <tr><td>Population générale caucasienne</td><td><span class=\"kw-chiffre\">6-8 %</span></td></tr>\n          <tr><td>SpA ankylosante</td><td><span class=\"kw-chiffre\">&gt; 90 %</span> — <span class=\"kw-chiffre\">RR &gt; 200</span></td></tr>\n          <tr><td>Arthrite réactionnelle</td><td><span class=\"kw-chiffre\">65-75 %</span></td></tr>\n          <tr><td>Rhumatisme psoriasique / entérocolopathies</td><td><span class=\"kw-chiffre\">50-70 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Interprétation (piège QCM ⭐).</strong>\n        <ul>\n          <li><span class=\"kw-bio\">HLA-B27 absent</span> : n'écarte pas le diagnostic — <span class=\"kw-chiffre\">10 %</span> des authentiques SpA ankylosantes sont B27-négatives.</li>\n          <li><span class=\"kw-bio\">HLA-B27 présent</span> : conforte sans affirmer — <span class=\"kw-chiffre\">97 %</span> des sujets B27-positifs n'auront <span class=\"kw-ci\">jamais de</span> SpA.</li>\n        </ul>\n      </div>\n\n      <h4 class=\"obj-sub\">Hypothèses physiopathologiques (rang C)</h4>\n      <ul>\n        <li><strong>Peptide arthritogène</strong> : certains <span class=\"kw-etio\">peptides microbiens</span> ressemblent aux peptides du soi pour le TCR de <span class=\"kw-bio\">LT CD8+</span> spécifiques du <span class=\"kw-bio\">HLA-B27</span> → autoréactivité.</li>\n        <li><strong>Stress du réticulum endoplasmique</strong> : mauvais repliement des chaînes du <span class=\"kw-bio\">HLA-B27</span> prolongeant sa présence dans le réticulum.</li>\n        <li><strong>Homodimérisation</strong> : <span class=\"kw-clinique\">les</span> chaînes lourdes du <span class=\"kw-bio\">HLA-B27</span> s'homodimérisent en surface, reconnues par des récepteurs de la voie <span class=\"kw-bio\">IL-17</span>.</li>\n      </ul>","frequence":1},{"id":"197-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’enthèse et l’enthésopathie inflammatoire (enthésite)","contenu":"<p>L'<strong><span class=\"kw-def\">enthèse</span></strong> est la zone d'ancrage dans l'os des structures fibreuses (<span class=\"kw-clinique\">ligaments</span>, <span class=\"kw-clinique\">tendons</span>, <span class=\"kw-clinique\">capsules articulaires</span>, <span class=\"kw-clinique\">fascias</span>). On la trouve au voisinage :</p>\n      <ul>\n        <li>des <strong>articulations synoviales</strong> ;</li>\n        <li>des <strong>amphiarthroses</strong> (symphyse pubienne, articulation manubrio-sternale, disque intervertébral) ;</li>\n        <li>des <strong>diarthroses fibreuses</strong> (articulation sacro-iliaque, sterno- ou acromio-claviculaire).</li>\n      </ul>\n\n      <p>L'<strong><span class=\"kw-def\">enthésite</span></strong> (enthésopathie <span class=\"kw-etio\">inflammatoire</span>, axiale ou périphérique) est le <span class=\"kw-def\">phénomène central des SpA</span> — surtout l'enthésopathie <strong>périphérique</strong>. C'est l'élément qui oppose la SpA à la <span class=\"kw-def\">polyarthrite rhumatoïde</span>, où l'atteinte principale est la <span class=\"kw-clinique\">synovite</span>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Physiopathologie</span>.</strong> <span class=\"kw-clinique\">Les</span> enthèses sont des zones à <span class=\"kw-etio\">forte pression mécanique</span> (surtout aux membres inférieurs) ; ce stress mécanique déclencherait l'enthésite chez des sujets prédisposés, via deux cytokines clés :\n        <ul>\n          <li><strong><span class=\"kw-bio\">TNFα</span></strong> → cible des biothérapies <span class=\"kw-ttt\">anti-TNFα</span>.</li>\n          <li><strong><span class=\"kw-bio\">IL-17</span></strong> → cible des biothérapies <span class=\"kw-ttt\">anti-IL-17</span>.</li>\n        </ul>\n      </div>\n\n      <h4 class=\"obj-sub\">Localisations préférentielles</h4>\n      <ul>\n        <li><strong>Membres inférieurs</strong> : enthésites <span class=\"kw-clinique\">calcanéennes</span> (<span class=\"kw-clinique\">les</span> plus fréquentes), <span class=\"kw-clinique\">patellaires</span>.</li>\n        <li>Rechercher systématiquement par palpation et mise en tension : <span class=\"kw-clinique\">tubérosité tibiale antérieure</span>, <span class=\"kw-clinique\">grand trochanter</span>, <span class=\"kw-clinique\">ischion</span>.</li>\n      </ul>\n\n      <h4 class=\"obj-sub\">Clinique</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur locale</span> d'horaire <span class=\"kw-clinique\">inflammatoire</span>, réveillée à l'examen par la <span class=\"kw-clinique\">pression</span> et la <span class=\"kw-clinique\">mise en tension de l'enthèse</span>.</li>\n        <li><span class=\"kw-clinique\">Tuméfaction locale</span> si enthésite superficielle très <span class=\"kw-etio\">inflammatoire</span> (ex. enthésite achilléenne ou calcanéenne postérieure).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Risque évolutif.</strong> L'inflammation peut précéder un <span class=\"kw-alerte\">processus d'ossification</span> : au rachis, formation de <span class=\"kw-imagerie\">syndesmophytes</span> puis de <span class=\"kw-imagerie\">ponts osseux</span> intervertébraux → <span class=\"kw-alerte\">ankylose vertébrale irréversible</span>.\n      </div>","frequence":0},{"id":"197-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes articulaires et périarticulaires","contenu":"<p>Trois grands tableaux articulaires et périarticulaires se combinent : <strong>syndrome pelvi-rachidien (axial)</strong>, <strong>syndrome articulaire périphérique</strong> et <strong>enthésopathie périphérique</strong>.</p>\n\n      <h4 class=\"obj-sub\">1 · Syndrome pelvi-rachidien (axial <span class=\"kw-etio\">inflammatoire</span>)</h4>\n      <p><strong>Inflammation des enthèses du rachis</strong> : <span class=\"kw-clinique\">dorso-lombalgies inflammatoires</span> présentes depuis <span class=\"kw-chiffre\">≥ 3 mois</span>. Atteinte initiale de la charnière thoraco-lombaire, puis extension :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Raideur axiale</span> : diminution de l'<span class=\"kw-clinique\">indice de Schöber</span>, augmentation de la <span class=\"kw-clinique\">distance main-sol</span>, perte de l'inflexion latérale lombaire.</li>\n        <li><span class=\"kw-alerte\">Ankylose rachidienne</span> (stades évolués) : disparition de la lordose lombaire (distance L3-mur).</li>\n        <li><strong>Rachis thoracique :</strong> <span class=\"kw-alerte\">exagération de la cyphose dorsale</span> (pouvant conduire à un flessum des hanches) ; <span class=\"kw-alerte\">diminution de l'ampliation thoracique → syndrome restrictif</span>.</li>\n        <li><strong>Rachis cervical :</strong> projection antérieure du massif cervicofacial (perte du regard horizontal) ; <span class=\"kw-alerte\">risque de fractures transdiscales/corporéales très instables</span> en cas d'ankylose → compression médullaire en cas de chute.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Mesure</th><th>Valeur normale</th></tr></thead>\n        <tbody>\n          <tr><td>Indice de Schöber (charnière thoraco-lombaire)</td><td><span class=\"kw-chiffre\">&gt; 10 + 4 cm</span></td></tr>\n          <tr><td>Distance main-sol (souplesse globale)</td><td><span class=\"kw-chiffre\">0-10 cm</span></td></tr>\n          <tr><td>Distance L3-mur</td><td>Évalue la lordose lombaire</td></tr>\n          <tr><td>Ampliation thoracique</td><td><span class=\"kw-chiffre\">&gt; 6 cm</span> entre inspiration et expiration</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong><span class=\"kw-imagerie\">Sacro-iliite</span> (inflammation des sacro-iliaques)</strong> — <span class=\"kw-clinique\">pygalgies / fessalgies</span> :</p>\n      <ul>\n        <li>Mode d'apparition : <span class=\"kw-clinique\">brutal</span> ; latéralité <span class=\"kw-clinique\">unilatérale</span>, <span class=\"kw-clinique\">bilatérale</span> ou <span class=\"kw-clinique\">à bascule</span>.</li>\n        <li>Horaire le plus souvent <span class=\"kw-clinique\">inflammatoire</span>, irradiant parfois en dessous du pli fessier (<strong><span class=\"kw-def\">sciatalgie tronquée</span></strong> ⭐).</li>\n        <li><span class=\"kw-clinique\">Signes négatifs</span> : aucun caractère neurogène (pas de dysesthésie), pas de trajet radiculaire complet, pas d'impulsivité à la <span class=\"kw-clinique\">toux</span>, pas de déficit neurologique objectif.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/197/faber-patrick-test.png\" alt=\"Manœuvre de Patrick (FABER) : flexion-abduction-rotation externe de hanche réveillant une douleur sacro-iliaque\" loading=\"lazy\">\n        <figcaption>Test de <span class=\"kw-clinique\">Patrick (FABER)</span> : flexion, abduction, rotation externe de la hanche — reproduit une douleur d'origine <span class=\"kw-imagerie\">sacro-iliaque</span>. Source : fiche source EDN item 197 — Spondylarthrite.</figcaption>\n      </figure>\n      <p>L'origine sacro-iliaque est confirmée si <span class=\"kw-chiffre\">≥ 3 manœuvres</span> de cisaillement sont positives, maintenues <span class=\"kw-chiffre\">≥ 20 secondes</span> chacune : <span class=\"kw-clinique\">FABER (Patrick)</span>, écartement des sacro-iliaques (appui sur <span class=\"kw-clinique\">les</span> 2 EIAS), rapprochement des ailes iliaques, signe du trépied (appui sacrum), cisaillement vertical, cisaillement horizontal (<span class=\"kw-clinique\">test de Gaenslen</span>).</p>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span> d'une fessalgie irradiant à la face postérieure de cuisse :</strong> <span class=\"kw-clinique\">radiculaire S1</span> <span class=\"kw-bio\">vs</span> douleur d'origine <span class=\"kw-clinique\">sacro-iliaque</span>. À l'inverse : atteinte <span class=\"kw-clinique\">radiculaire L4</span> et douleur <span class=\"kw-clinique\">coxofémorale</span> → <span class=\"kw-clinique\">irradiation</span> à la face <strong>antérieure</strong> ; tendinite du moyen fessier → douleur du grand trochanter (pas de fessalgie).\n      </div>\n\n      <h4 class=\"obj-sub\">2 · Syndrome articulaire périphérique</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Oligoarthrite des membres inférieurs</span> touchant volontiers <span class=\"kw-clinique\">les</span> grosses articulations : <strong>genou &gt; cheville &gt; hanche</strong> (la <span class=\"kw-alerte\">coxite</span> est fréquente et redoutable).</li>\n        <li>Arthrites des articulations <span class=\"kw-clinique\">IPD</span> (surtout dans le rhumatisme psoriasique).</li>\n        <li><span class=\"kw-clinique\">Dactylites</span> : atteinte <span class=\"kw-etio\">inflammatoire</span> globale d'un doigt ou orteil « en saucisse ».</li>\n      </ul>\n\n      <h4 class=\"obj-sub\">3 · Enthésopathie périphérique</h4>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Talalgie</strong> (calcanéenne — la plus fréquente et caractéristique)</td><td><strong><span class=\"kw-def\">Terrain</span> :</strong> très évocatrice chez le sujet jeune<br><strong>Horaire :</strong> <span class=\"kw-clinique\">inflammatoire</span>, au lever lors du 1ᵉʳ pas, s'améliore dans la journée<br><strong>Topographie :</strong> plantaire inférieure (<span class=\"kw-clinique\">aponévrosite plantaire</span>) ou postérieure (<span class=\"kw-clinique\">enthésopathie du tendon calcanéen</span>, bursite pré/rétro-achilléenne)</td></tr>\n          <tr><td><strong>Dactylite</strong></td><td>Orteil ou doigt « en saucisse » (cf. objectif dédié)</td></tr>\n          <tr><td><strong>Paroi thoracique antérieure</strong></td><td>Articulations <span class=\"kw-clinique\">sterno-claviculaires</span>, <span class=\"kw-clinique\">manubrio-sternale</span>, <span class=\"kw-clinique\">chondro-sternales</span></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 198 — Arthropathie microcristalline · 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span></em></p>","frequence":0,"liens":[{"href":"https://www.piriforme.fr/bdd/orthopedie/bassin/cisaillement","label":"Manœuvres de cisaillement sacro-iliaque"}]},{"id":"197-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes extra-articulaires","contenu":"<p><span class=\"kw-clinique\">Les</span> manifestations extra-articulaires peuvent <strong>précéder</strong> les manifestations rhumatologiques et orientent fortement le diagnostic.</p>\n\n      <h4 class=\"obj-sub\">Manifestations extra-articulaires</h4>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Uvéite aiguë antérieure</span></strong></td><td>Uni/bilatérale ou à bascule, <span class=\"kw-clinique\">récidivante</span>, souvent à <span class=\"kw-clinique\">hypopion</span>, <span class=\"kw-clinique\">non granulomateuse</span> ; survient dans <span class=\"kw-chiffre\">20-30 %</span> des cas, parfois inaugurale ; traitement par <span class=\"kw-ttt\">collyres cortisoniques</span> + <span class=\"kw-ttt\">mydriatiques</span> ; bon <span class=\"kw-def\">pronostic</span> (risque de synéchies si répétée sans traitement)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Entérocolopathie inflammatoire</span></strong> (<span class=\"kw-clinique\">MICI</span>)</td><td><span class=\"kw-clinique\">Diarrhée</span> banale ou glairo-sanglante, <span class=\"kw-clinique\">selles nocturnes</span> ++, <span class=\"kw-clinique\">amaigrissement</span> inexpliqué</td></tr>\n          <tr><td><strong>Infection urogénitale / digestive</strong></td><td>Évoque une <span class=\"kw-def\">arthrite réactionnelle</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Psoriasis</span></strong></td><td><strong>Zones bastions :</strong> cuir chevelu, <span class=\"kw-clinique\">psoriasis</span> unguéal, psoriasis inversé (sillon interfessier)<br><strong>Formes :</strong> vulgaire en plaques, en gouttes<br><strong>Pustulose palmoplantaire</strong> → évoquer le syndrome <span class=\"kw-def\">SAPHO</span><br><strong>Hidrosadénite suppurée</strong> (maladie de Verneuil)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Complications propres / atteintes systémiques (rares, formes anciennes non traitées)</h4>\n      <table >\n        <thead><tr><th>Organe</th><th>Complication</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Os</strong></td><td><span class=\"kw-clinique\">Ostéoporose</span> et <span class=\"kw-alerte\">risque fracturaire</span> (surtout sur « colonne bambou » cervicale : fractures transcorporéales/transdiscales instables → complications neurologiques)</td></tr>\n          <tr><td><strong>Poumon</strong></td><td>Dysplasies bulleuses kystiques des apex ; <span class=\"kw-clinique\">fibrose pulmonaire</span> et surtout <span class=\"kw-alerte\">syndrome restrictif</span></td></tr>\n          <tr><td><strong>Cœur</strong></td><td>Valvulopathies tardives (<span class=\"kw-clinique\">insuffisance aortique</span>), <span class=\"kw-clinique\">troubles du rythme/conduction</span> lors des poussées ; sur-risque CV (<span class=\"kw-alerte\">AVC</span>, <span class=\"kw-alerte\">IDM</span>)</td></tr>\n          <tr><td><strong>Neurologique</strong></td><td>Dilatation du cul-de-sac dural (formes anciennes) : <span class=\"kw-clinique\">troubles sensitivomoteurs</span> des MI, <span class=\"kw-clinique\">troubles génito-sphinctériens</span> → <span class=\"kw-imagerie\">IRM lombaire</span> diagnostique, dérivation du <span class=\"kw-bio\">LCR</span></td></tr>\n          <tr><td><strong>Amylose</strong></td><td><span class=\"kw-alerte\">Amylose AA</span> due à l'inflammation chronique non maîtrisée (rarissime mais peut être fatale)</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 83 — Infection et inflammations occulaires · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0},{"id":"197-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères cliniques biologiques et radiologiques","contenu":"<div class=\"callout callout-info\">\n        <strong>Principe ⚠️.</strong> Aucun élément clinique ou examen complémentaire n'est suffisant à lui seul (pas de « test diagnostique » auto-suffisant). Le diagnostic repose sur un <span class=\"kw-def\">faisceau d'arguments</span>, d'autant plus probant que <span class=\"kw-clinique\">les</span> éléments sont multiples, surtout s'il s'agit de manifestations inflammatoires objectivables (<span class=\"kw-clinique\">dactylite</span>, <span class=\"kw-clinique\">arthrite</span>, aspect <span class=\"kw-imagerie\">radiographique</span> ou <span class=\"kw-imagerie\">IRM</span> anormal).\n      </div>\n\n      <h4 class=\"obj-sub\">Critères ASAS 2009 — référence actuelle (de <span class=\"kw-def\">classification</span>, non diagnostiques)</h4>\n      <p><strong>SpA axiale</strong> — chez <span class=\"kw-clinique\">les</span> patients de <span class=\"kw-chiffre\">&lt; 45 ans</span> avec rachialgies <span class=\"kw-chiffre\">&gt; 3 mois</span>. Le patient est classé SpA axiale s'il a :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Sacro-iliite à l'imagerie</span> + <span class=\"kw-chiffre\">≥ 1</span> signe de SpA, <strong>OU</strong></li>\n        <li><span class=\"kw-bio\">HLA-B27 positif</span> + <span class=\"kw-chiffre\">≥ 2</span> signes de SpA.</li>\n      </ul>\n      <p><strong>Signes de SpA :</strong> rachialgie <span class=\"kw-etio\">inflammatoire</span>, arthrite, enthésite (talon), uvéite, dactylite, <span class=\"kw-clinique\">psoriasis</span>, Crohn/<span class=\"kw-clinique\">RCH</span>, bonne réponse aux <span class=\"kw-ttt\">AINS</span>, antécédent familial de SpA, <span class=\"kw-bio\">HLA-B27</span>, <span class=\"kw-bio\">CRP élevée</span>.</p>\n      <p>Performances : sensibilité <span class=\"kw-chiffre\">82 %</span>, spécificité <span class=\"kw-chiffre\">84,4 %</span> ; imagerie seule : Se <span class=\"kw-chiffre\">66,2 %</span>, Sp <span class=\"kw-chiffre\">97,3 %</span>.</p>\n\n      <p><strong>SpA périphérique</strong> — <span class=\"kw-clinique\">arthrite</span> ou <span class=\"kw-clinique\">enthésite</span> ou <span class=\"kw-clinique\">dactylite</span> + :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">≥ 1</span> critère parmi : uvéite, <span class=\"kw-clinique\">psoriasis</span>, Crohn/<span class=\"kw-clinique\">RCH</span>, infection préalable, <span class=\"kw-bio\">HLA-B27</span>, sacro-iliite à l'imagerie, <strong>OU</strong></li>\n        <li><span class=\"kw-chiffre\">≥ 2</span> autres critères parmi : arthrite, enthésite, dactylite, rachialgie <span class=\"kw-etio\">inflammatoire</span>, antécédent familial de SpA.</li>\n      </ul>\n      <p>Performances : sensibilité <span class=\"kw-chiffre\">77,8 %</span>, spécificité <span class=\"kw-chiffre\">82,2 %</span>.</p>\n\n      <h4 class=\"obj-sub\"><span class=\"kw-def\">Critères de</span> New-York modifiés — SpA ankylosante (rang C)</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critères cliniques</span></th><th>Critères radiologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-clinique\">Lombalgies + raideur</span> &gt;<span class=\"kw-chiffre\"> 3 mois</span>, améliorées par l'effort mais ne cédant pas au repos<br>\n              <span class=\"kw-clinique\">Limitation du rachis lombaire</span> dans <span class=\"kw-clinique\">les</span> plans frontal et sagittal<br>\n              <span class=\"kw-clinique\">Limitation de l'ampliation thoracique</span> (selon âge/sexe)\n            </td>\n            <td>\n              <span class=\"kw-imagerie\">Sacro-iliite bilatérale</span> de <span class=\"kw-chiffre\">stade ≥ 2</span><br>\n              <strong>OU</strong> <span class=\"kw-imagerie\">sacro-iliite unilatérale</span> de <span class=\"kw-chiffre\">stade ≥ 3</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La SpA ankylosante est définie <strong>lorsqu'un critère radiologique est associé à au moins un <span class=\"kw-def\">critère clinique</span></strong>.</p>\n\n      <h4 class=\"obj-sub\">Critères biologiques</h4>\n      <p><span class=\"kw-bio\">CRP</span> et <span class=\"kw-bio\">VS</span> élevées chez <span class=\"kw-chiffre\">60 %</span> des SpA non traitées, mais le <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> est habituellement <span class=\"kw-clinique\">plus modeste</span> que dans la <span class=\"kw-clinique\">PR</span>. Une <span class=\"kw-alerte\">élévation importante</span> doit faire rechercher une affection associée (<span class=\"kw-etio\">tumorale</span>, infectieuse, <span class=\"kw-clinique\">MICI</span> méconnue).</p>","frequence":2,"liens":[{"href":"https://www.imosteo.com/asas-2009-le-grand-malentendu/","label":"Critères ASAS 2009 — explications"}]},{"id":"197-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différents types de spondyloarthrites","contenu":"<table >\n        <thead><tr><th>Type</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">SpA ankylosante</span></strong> (axiale radiographique)</td>\n            <td>\n              <strong>Atteinte :</strong> squelette axial (rachis + sacro-iliaques) → <span class=\"kw-alerte\">ankylose</span><br>\n              <strong>Diagnostic :</strong> syndrome pelvi-rachidien <span class=\"kw-etio\">inflammatoire</span> + <span class=\"kw-imagerie\">sacro-iliite radiologique</span> (<span class=\"kw-def\">stade</span> 2 bilatérale ou <span class=\"kw-chiffre\">stade 3</span> unilatérale, indispensable)<br>\n              <strong>Associé :</strong> atteinte périphérique <span class=\"kw-chiffre\">50 %</span> ; <span class=\"kw-clinique\">uvéite antérieure</span> <span class=\"kw-chiffre\">10-30 %</span><br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> chronique par poussées sur <span class=\"kw-chiffre\">10-20 ans</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Rhumatisme psoriasique</span></strong></td>\n            <td>Une des formes périphériques <span class=\"kw-clinique\">les</span> plus fréquentes ; <span class=\"kw-clinique\">dactylite</span> et atteinte <span class=\"kw-clinique\">IPD</span> évocatrices (critères CASPAR)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Arthrites réactionnelles</span></strong> (<span class=\"kw-clinique\">syndrome de Reiter</span>)</td>\n            <td>\n              Arthrites <span class=\"kw-clinique\">aseptiques</span> survenant quelques semaines (<span class=\"kw-chiffre\">&lt; 1 mois</span>) après une infection :<br>\n              <strong>Génitale :</strong> <span class=\"kw-etio\">Chlamydia trachomatis</span> +++, <span class=\"kw-etio\">Mycoplasma</span><br>\n              <strong>Digestive :</strong> <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">Yersinia</span>, <span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Campylobacter jejuni</span><br>\n              <strong><span class=\"kw-bio\">HLA-B27</span> :</strong> <span class=\"kw-chiffre\">50-95 %</span> · Triade de <span class=\"kw-def\">Fiessinger-Leroy-Reiter</span> : <span class=\"kw-clinique\">urétrite</span>/cervicite + conjonctivite + arthrite (radios normales)<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> chronique dans <span class=\"kw-chiffre\">10-20 %</span> → peut évoluer vers une <span class=\"kw-alerte\">SpA ankylosante</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Arthrites des entérocolopathies</span></strong> (<span class=\"kw-clinique\">MICI</span>)</td>\n            <td>\n              <strong>Périphériques / sacro-iliite :</strong> <span class=\"kw-chiffre\">10-20 %</span> des <span class=\"kw-clinique\">MICI</span>, évoluent <em>parallèlement</em> à l'atteinte digestive<br>\n              <strong>Forme axiale complète :</strong> plus rare (<span class=\"kw-chiffre\">&lt; 5 %</span>), évolue <em>indépendamment</em> de l'atteinte digestive\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Formes juvéniles · SpA indifférenciées · SAPHO</strong></td>\n            <td>SAPHO : <span class=\"kw-clinique\">synovite</span>, <span class=\"kw-clinique\">acné</span>, <span class=\"kw-clinique\">pustulose</span>, <span class=\"kw-clinique\">hyperostose</span>, <span class=\"kw-clinique\">ostéite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 117 — <span class=\"kw-clinique\">Psoriasis</span> · 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/reactive-arthritis","label":"Radiopaedia : Reactive arthritis"}]},{"id":"197-9","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une dactylite","contenu":"<p>La <strong><span class=\"kw-def\">dactylite</span></strong> est une atteinte <span class=\"kw-etio\">inflammatoire</span> de l'<strong>ensemble</strong> d'un doigt ou d'un orteil, réalisant un aspect <strong>« en saucisse »</strong> : <span class=\"kw-clinique\">tuméfaction globale</span> de l'orteil ou du doigt, avec <span class=\"kw-clinique\">rougeur</span>.</p>\n\n      <h4 class=\"obj-sub\">Substratum lésionnel (le plus souvent l'association)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Enthésopathie inflammatoire distale</span> ;</li>\n        <li><span class=\"kw-clinique\">Ténosynovite</span> ;</li>\n        <li><span class=\"kw-clinique\">Arthrite</span> le plus souvent <strong>tripolaire</strong> : <span class=\"kw-clinique\">métacarpo/métatarso-phalangienne</span> + <span class=\"kw-clinique\">IPP</span> + <span class=\"kw-clinique\">IPD</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span>.</strong> Au niveau du 1ᵉʳ rayon, la <span class=\"kw-clinique\">dactylite</span> ne doit <strong>pas</strong> être confondue avec l'atteinte exclusive de l'articulation <span class=\"kw-clinique\">métatarso-phalangienne</span>, évocatrice de <span class=\"kw-etio\">goutte</span>.\n      </div>\n\n      <h4 class=\"obj-sub\">Étiologies</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Rhumatisme psoriasique</span> : signe clinique majeur, retenu dans <span class=\"kw-clinique\">les</span> critères <span class=\"kw-def\">CASPAR</span> ;</li>\n        <li><span class=\"kw-etio\">Spondyloarthrites axiales</span> ;</li>\n        <li>Plus rarement (selon l'abrégé) : <span class=\"kw-etio\">arthrite</span>, <span class=\"kw-etio\">goutte</span>, <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">maladie de Still</span>.</li>\n      </ul>\n\n      <!-- TODO Kevin : déposer une photographie clinique de dactylite (doigt/orteil \"en saucisse\") dans assets/images/197/ — non disponible dans la fiche source ni dans IMAGERIE A CONNAITRE.pdf. Lien Radiopaedia en attendant. -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 198 — Arthropathie microcristalline · 117 — <span class=\"kw-clinique\">Psoriasis</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/sausage-digit","label":"Radiopaedia : Sausage digit (dactylite)"}]},{"id":"197-10","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie du rachis","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/197/syndesmophyte-vs-osteophyte.png\" alt=\"Schéma comparatif rachis lombaire : syndesmophyte (ossification fine verticale du ligament/annulus, lésion de Romanus) versus ostéophyte (excroissance grossière horizontale, sclérose, dégénérescence discale)\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Syndesmophyte</span> (à gauche) : ossification fine et verticale de l'annulus fibrosus et des l<span class=\"kw-chiffre\">iga</span>ments — <span class=\"kw-clinique\">lésion</span> de Romanus, <span class=\"kw-def\">spécifique d'une SpA</span>. <span class=\"kw-imagerie\">Ostéophyte</span> (à droite) : excroissance grossière et horizontale avec <span class=\"kw-ttt\">sclérose</span> et dégénérescence discale — <span class=\"kw-etio\">arthrose</span>. Source : fiche source EDN item 197 (illustration didactique).</figcaption>\n      </figure>\n\n      <h4 class=\"obj-sub\"><span class=\"kw-clinique\">Évolution</span> radiologique de la charnière thoraco-lombaire</h4>\n      <ol>\n        <li><span class=\"kw-imagerie\">Érosion inflammatoire de l'angle antérieur de la vertèbre</span> (<span class=\"kw-def\">spondylite antérieure de Romanus</span>) → « mise au carré » de la vertèbre (<em>squaring</em>).</li>\n        <li>Formation de <span class=\"kw-imagerie\">syndesmophytes</span> (ossification d'une enthèse vertébrale).</li>\n        <li>Syndesmophytes ascendants ou descendants.</li>\n        <li><span class=\"kw-imagerie\">Ossification des ligaments intervertébraux</span> dans <span class=\"kw-clinique\">les</span> formes ankylosantes.</li>\n        <li>Classique <span class=\"kw-imagerie\">« colonne bambou »</span> / aspect en « rail de chemin de fer » sur <span class=\"kw-clinique\">les</span> clichés de face.</li>\n      </ol>\n\n      <h4 class=\"obj-sub\">Distinguer <span class=\"kw-clinique\">les</span> ossifications (piège QCM)</h4>\n      <table >\n        <thead><tr><th></th><th>Enthésophyte</th><th>Ostéophyte</th><th>Syndesmophyte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Ossification le long d'une <span class=\"kw-imagerie\">enthèse périphérique</span> (ex. épine calcanéenne)</td>\n            <td>Excroissance osseuse en périphérie d'une articulation / partie antérieure d'une vertèbre (« bec de perroquet »)</td>\n            <td>Ossification d'une <span class=\"kw-imagerie\">enthèse vertébrale</span>, peut fusionner 2 vertèbres</td>\n          </tr>\n          <tr>\n            <td><strong>Aspect</strong></td>\n            <td>—</td>\n            <td><span class=\"kw-imagerie\">Grossier</span>, direction <span class=\"kw-imagerie\">horizontale</span></td>\n            <td><span class=\"kw-imagerie\">Fin</span>, direction <span class=\"kw-imagerie\">verticale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Étiologie</strong></td>\n            <td>Non spécifique (sur-sollicitation mécanique)</td>\n            <td><span class=\"kw-etio\">Arthrose</span></td>\n            <td><span class=\"kw-def\">Spécifique d'une spondyloarthrite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Clichés du rachis à réaliser</h4>\n      <ul>\n        <li>Rachis cervical, thoracique, lombaire : <strong>face et profil</strong>.</li>\n        <li>Rachis cervical : <span class=\"kw-imagerie\">face bouche ouverte</span>, <span class=\"kw-imagerie\">profil</span> et <span class=\"kw-imagerie\">profil en flexion</span> (<span class=\"kw-clinique\">les</span> ¾ et la face sont inutiles).</li>\n      </ul>","frequence":0},{"id":"197-11","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie du bassin","contenu":"<p>Le <strong>bassin de face</strong> est le cliché clé : il recherche la <strong><span class=\"kw-imagerie\">sacro-iliite</span></strong>, dont l'<span class=\"kw-clinique\">enthésopathie</span> siège à la partie basse de l'<span class=\"kw-imagerie\">articulation sacro-iliaque</span> et connaît <span class=\"kw-chiffre\">4 phases</span> évolutives (<span class=\"kw-def\">classification</span> de <span class=\"kw-def\">New-York</span>).</p>\n\n      <h4 class=\"obj-sub\">Stades de New-York de la sacro-iliite</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Aspect radiologique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 0</strong></td><td>Aspect <span class=\"kw-imagerie\">normal</span> des sacro-iliaques</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 1</strong></td><td>Sacro-iliite <span class=\"kw-imagerie\">douteuse</span> : <span class=\"kw-imagerie\">sclérose</span> et altération focalisée de l'<span class=\"kw-imagerie\">interligne</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 2</strong></td><td>Sacro-iliite <span class=\"kw-imagerie\">modérée</span> : <span class=\"kw-imagerie\">pseudo-élargissement</span>, <span class=\"kw-imagerie\">érosions</span> et <span class=\"kw-imagerie\">sclérose</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 3</strong></td><td>Sacro-iliite <span class=\"kw-imagerie\">avérée</span> : <span class=\"kw-imagerie\">sclérose et érosions franches</span> (aspect « en timbre-poste »)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 4</strong></td><td><span class=\"kw-imagerie\">Ankylose</span> sacro-iliaque</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Mnémo (stades de <span class=\"kw-def\">Forestier</span>) — EFICA :</strong> <strong>É</strong>largissement et <strong>F</strong>lou des <span class=\"kw-imagerie\">berges</span> (1) · <strong>I</strong>rrégularité et <span class=\"kw-imagerie\">érosions</span> des berges (2) · <strong>C</strong>ondensation des berges (3) · <strong>A</strong>nkylose complète (4).\n      </div>\n\n      <p>La <span class=\"kw-imagerie\">coxite</span> (atteinte coxo-fémorale) peut également être recherchée sur le bassin. Pour la SpA ankylosante, <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> New-York retiennent une <span class=\"kw-imagerie\">sacro-iliite bilatérale ≥ stade 2</span> ou <span class=\"kw-imagerie\">unilatérale ≥ stade 3</span>.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/197/rx-bassin-coxite-sacro-iliite-de-seze.png\" alt=\"Radiographie du bassin de face (cliché de De Sèze) — incidence de référence pour rechercher une sacro-iliite et une coxite\" loading=\"lazy\">\n        <figcaption>Bassin de face (cliché de De Sèze) : <span class=\"kw-def\">incidence</span> clé pour rechercher une sacro-iliite (condensation/érosions des berges, aspect « timbre-poste ») et une coxite coxo-fémorale. Source : IMAGERIE A CONNAITRE (EDN item 197, p.32).</figcaption>\n      </figure>","frequence":0},{"id":"197-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’utilisation rationnelle des examens biologiques et d’imagerie","contenu":"<h4 class=\"obj-sub\">Biologie</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Utilisation rationnelle</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">CRP, VS</span></strong></td><td>Élevées chez <span class=\"kw-chiffre\">60 %</span> des SpA non traitées ; <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> <span class=\"kw-clinique\">plus modeste</span> que dans la <span class=\"kw-clinique\">PR</span>. <span class=\"kw-alerte\">Élévation importante</span> → rechercher une affection associée (<span class=\"kw-etio\">tumorale</span>, infectieuse, <span class=\"kw-clinique\">MICI</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">HLA-B27</span></strong></td><td><span class=\"kw-clinique\">Inutile</span> si la SpA est certaine ; demandé seulement <strong>en cas de doute</strong> (applique <span class=\"kw-clinique\">les</span> critères ASAS).<br><strong>Absent :</strong> n'écarte pas (<span class=\"kw-chiffre\">10 %</span> de SpA B27−).<br><strong>Présent :</strong> conforte sans affirmer (<span class=\"kw-chiffre\">97 %</span> des B27+ sans SpA)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Imagerie</h4>\n      <table >\n        <thead><tr><th>Modalité</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie standard</span></strong></td><td>1ʳᵉ intention : sacro-iliaques, rachis, bassin (sacro-iliite, syndesmophytes, ankylose)</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">IRM</span></strong></td><td>Argument pour le <span class=\"kw-clinique\">diagnostic précoce</span> (remaniements inflammatoires précédant <span class=\"kw-clinique\">les</span> lésions radiographiques) ; mais <span class=\"kw-alerte\">spécificité imparfaite</span> (<span class=\"kw-etio\">obésité</span>, âge, <span class=\"kw-ci\">grossesse</span> récente, sport intensif, arthrose). Pas d'intérêt supplémentaire si la sacro-iliite est déjà visible en <span class=\"kw-imagerie\">radiographie</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie-Doppler</span></strong> (rang C)</td><td>Affine le diagnostic des enthésopathies périphériques</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Scintigraphie ⁹⁹ᵐTc</span></strong> (rang C)</td><td>Utilité rarissime, parfois dans le SAPHO ; spécificité faible</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Clichés radiologiques : <span class=\"kw-clinique\">PR</span> <span class=\"kw-bio\">vs</span> SpA (point très discriminant ⭐⭐).</strong>\n        <ul>\n          <li><strong>SpA ankylosante :</strong> <span class=\"kw-alerte\">pas de radio des mains</span> ; <span class=\"kw-imagerie\">pieds de profil</span> (épines calcanéennes) ; <span class=\"kw-imagerie\">bassin de face</span> + rachis dorso-lombaire (<strong>cliché de Sèze</strong>) + rachis thoracique ; rachis cervical (profil, profil en flexion, face bouche ouverte) ; rachis lombaire de ¾ ; thorax face/profil.</li>\n          <li><strong><span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> :</strong> <span class=\"kw-imagerie\">mains et poignets</span> de face ; <span class=\"kw-imagerie\">pieds</span> ¾ et face ; bassin (coxite) ; thorax. <span class=\"kw-def\">Surveillance</span> plus intensive (tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> la 1ʳᵉ année — « tight control »).</li>\n        </ul>\n      </div>\n\n      <p>Selon <span class=\"kw-clinique\">les</span> complications : <span class=\"kw-bio\">EFR</span> (atteinte respiratoire restrictive, fibrose) et <span class=\"kw-bio\">ECG</span> (troubles du rythme/conduction).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span></em></p>","frequence":2,"liens":[{"href":"https://onclepaul.net/wp-content/uploads/2011/07/Aspects-radio.-des-coxites-rhumatismalesFILEminimizer.pdf","label":"Aspects radiologiques des coxites rhumatismales (PDF)"}]},{"id":"197-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","contenu":"<div class=\"callout callout-info\">\n        <strong>🎯 Objectif thérapeutique :</strong> <span class=\"kw-def\">rémission</span> ou <span class=\"kw-def\">activité faible</span> de la maladie. Réponse évaluée sur l'<span class=\"kw-bio\">EVA</span>, le <span class=\"kw-bio\">syndrome inflammatoire</span> et <span class=\"kw-clinique\">les</span> scores d'activité (<span class=\"kw-bio\">BASDAI</span>, <span class=\"kw-bio\">ASDAS</span>).\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/197/algorithme-sfr-2022-spa.png\" alt=\"Algorithme thérapeutique SFR 2022 : AINS ± infiltration en première ligne, puis traitement ciblé (anti-TNF, anti-IL17, JAKi, anti-IL23, anti-IL12/23) selon le phénotype axial, périphérique articulaire ou enthésitique/dactylitique\" loading=\"lazy\">\n        <figcaption>Algorithme de prise en charge de la spondyloarthrite active — <span class=\"kw-ttt\">AINS</span> ± <span class=\"kw-ttt\">infiltration</span> en 1ʳᵉ ligne, puis traitement ciblé selon le phénotype (axial / périphérique articulaire / enthésite-dactylite). Source : actualisation <span class=\"kw-def\">SFR 2022</span> (Wendling D et al., Rev Rhum 2022;89(3):210-22).</figcaption>\n      </figure>\n\n      <h4 class=\"obj-sub\"><span class=\"kw-ttt\">AINS</span> — pierre angulaire du traitement</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Efficacité</strong></td><td>Sur la lombalgie <span class=\"kw-etio\">inflammatoire</span> dans <span class=\"kw-chiffre\">70 %</span> des cas ; délai d'action rapide, rechute &lt;<span class=\"kw-chiffre\"> 48 h</span> après l'arrêt ; échec chez <span class=\"kw-chiffre\">25-50 %</span> des patients</td></tr>\n          <tr><td><strong>Familles</strong></td><td><span class=\"kw-clinique\">Les</span> plus actives : proprioniques, indoliques. Le <span class=\"kw-ci\">diclofénac</span> au long cours n'est plus admis (<span class=\"kw-alerte\">risque cardiovasculaire</span>)</td></tr>\n          <tr><td><strong>Administration</strong></td><td>Dose optimale, prise le soir sous forme LP pour couvrir la phase <span class=\"kw-etio\">inflammatoire</span> nocturne/matinale</td></tr>\n          <tr><td><strong>Si échec</strong></td><td>Changer d'<span class=\"kw-ttt\">AINS</span> après <span class=\"kw-chiffre\">2 semaines</span> ; essayer <span class=\"kw-chiffre\">≥ 2 AINS</span> sur <span class=\"kw-chiffre\">4 semaines</span> au total avant de conclure à l'échec</td></tr>\n          <tr><td><strong>Précaution</strong></td><td><span class=\"kw-alerte\">Prudence si MICI associée</span> (risque d'ulcérations, hémorragie, perforation)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Traitement de fond (DMARD) — si réponse insuffisante aux <span class=\"kw-ttt\">AINS</span> et gestes locaux</h4>\n      <table >\n        <thead><tr><th>Indication</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Biothérapie</span> <span class=\"kw-ttt\">anti-TNFα</span> : <span class=\"kw-ttt\">adalimumab</span>, <span class=\"kw-ttt\">étanercept</span>, <span class=\"kw-ttt\">golimumab</span>, <span class=\"kw-ttt\">certolizumab pegol</span>, <span class=\"kw-ttt\">infliximab</span></td></tr>\n          <tr><td><strong>Utilisables dans toutes <span class=\"kw-clinique\">les</span> SpA</strong></td><td>Anti-TNFα ; <span class=\"kw-ttt\">biothérapie</span> <span class=\"kw-ttt\">anti-IL-17</span> : <span class=\"kw-ttt\">sécukinumab</span>, <span class=\"kw-ttt\">ixékizumab</span></td></tr>\n          <tr><td><strong>Seulement dans le rhumatisme psoriasique</strong></td><td>csDMARD : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">léflunomide</span> · tsDMARD : <span class=\"kw-ttt\">aprémilast</span> (PDE4i), <span class=\"kw-ttt\">tofacitinib</span> (JAKi) · bDMARD : <span class=\"kw-ttt\">ustékinumab</span> (anti-IL-12/IL-23)</td></tr>\n        </tbody>\n      </table>\n      <p>Traitements locaux si résistance : <span class=\"kw-ttt\">infiltration</span> de <span class=\"kw-ttt\">corticoïdes</span> (arthrite, enthésopathie), synoviorthèse isotopique. <span class=\"kw-ttt\">Antalgiques</span> en <span class=\"kw-bio\">complément</span> pour faciliter la rééducation.</p>\n\n      <h4 class=\"obj-sub\">Traitements non pharmacologiques</h4>\n      <div class=\"callout callout-warn\">\n        <strong>Activité physique régulière + kinésithérapie = indispensables.</strong> Elles visent à réduire le risque d'<span class=\"kw-alerte\">ankylose en mauvaise position</span>. <strong><span class=\"kw-clinique\">Les</span> biomédicaments n'ont pas d'effet sur le risque d'ankylose et ne dispensent pas de la kinésithérapie.</strong>\n      </div>\n      <ul>\n        <li>Autograndissement, postures anti-cyphose, mobilisation des hanches en extension, rééducation respiratoire ; éviter <span class=\"kw-clinique\">les</span> positions prolongées inappropriées (dormir « en chien de fusil »).</li>\n        <li>Physiothérapie, ergothérapie, appareillage.</li>\n        <li><strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-clinique\">arrêt du tabac indispensable</span> (progression de l'ankylose, moindre réponse aux anti-TNFα, <span class=\"kw-etio\">FRCV</span>) ; contrôle des <span class=\"kw-clinique\">FRCV</span> ; <span class=\"kw-def\">dépistage</span> de l'<span class=\"kw-clinique\">ostéoporose</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span> :</strong> prothèse articulaire (coxite), libération articulaire, ostéotomie rachidienne de correction (rare).</li>\n        <li><strong>Social :</strong> adaptation du poste de travail ; <span class=\"kw-def\">ALD 30</span> si SpA sévère.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 202 — Biothérapies, thérapies ciblées</em></p>","frequence":3},{"id":"197-14","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic à long terme","contenu":"<p><span class=\"kw-clinique\">Évolution</span> chronique par <span class=\"kw-clinique\">poussées</span> rompues de rémissions, sur <span class=\"kw-chiffre\">10-20 ans</span>. Le <span class=\"kw-def\">suivi</span> vise à prévenir l'ankylose et à dépister <span class=\"kw-clinique\">les</span> complications.</p>\n\n      <h4 class=\"obj-sub\">Modalités de <span class=\"kw-def\">suivi</span></h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Évaluation clinique tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span> selon l'<span class=\"kw-clinique\">évolution</span></td></tr>\n          <tr><td><strong>Clinique</strong></td><td><strong>Axial :</strong> EVA rachidienne, réveils nocturnes, mesures (Schöber, ampliation, raideur)<br><strong>Périphérique :</strong> nombre d'articulations douloureuses/gonflées<br><strong>Enthèses :</strong> comptage des enthèses douloureuses<br><strong>Extra-articulaire :</strong> <span class=\"kw-clinique\">uvéites</span>, <span class=\"kw-clinique\">MICI</span>, <span class=\"kw-clinique\">psoriasis</span> (<span class=\"kw-def\">score</span> PASI)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">CRP, VS</span> (si <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>) ; <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span> si <span class=\"kw-ttt\">AINS</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td><td>Formes évolutives : tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-3 ans</span> — rachis cervical de face, rachis lombaire face/profil, bassin</td></tr>\n          <tr><td><strong>Scores</strong></td><td><span class=\"kw-bio\">BASDAI</span>, <span class=\"kw-bio\">ASDAS</span> (activité, indication des <span class=\"kw-ttt\">anti-TNF</span>) ; <span class=\"kw-bio\">BASFI</span> (retentissement fonctionnel)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"obj-sub\">Facteurs de mauvais <span class=\"kw-def\">pronostic</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span> :</strong> début précoce (<span class=\"kw-chiffre\">&lt; 16 ans</span>), <span class=\"kw-clinique\">tabagisme actif</span> ;</li>\n        <li><strong>Clinique :</strong> <span class=\"kw-alerte\">coxite</span>, <span class=\"kw-clinique\">dactylite</span> ;</li>\n        <li><strong>Paraclinique :</strong> <span class=\"kw-bio\">syndrome inflammatoire important</span>, <span class=\"kw-imagerie\">syndesmophytes au diagnostic</span> ;</li>\n        <li><strong>Réponse au traitement :</strong> <span class=\"kw-alerte\">résistance aux AINS</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Sources de handicap.</strong> L'<span class=\"kw-alerte\">ankylose rachidienne constituée n'est pas récupérable par la rééducation</span> ⚠️. S'y ajoutent l'atteinte osseuse (ostéoporose, fractures de la « colonne bambou »), l'atteinte des hanches et l'atteinte restrictive pulmonaire.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante · 93 — Compression médullaire non trauma</em></p>","frequence":0,"liens":[{"href":"http://medicalcul.free.fr/basdai.html","label":"Calculateur BASDAI"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-def\">rhumatisme inflammatoire chronique</span>, pas une urgence en soi, mais complications graves à dépister<br><strong>Fracture rachidienne :</strong> rachialgie aiguë sur <span class=\"kw-radio\">colonne bambou</span> cervicale → <span class=\"kw-alerte\">fracture transcorporéale/transdiscale instable</span> avec <span class=\"kw-alerte\">risque de compression médullaire si chute</span><br><strong>Uvéite aiguë antérieure :</strong> avis ophtalmologique, <span class=\"kw-ttt\">collyres cortisoniques</span> + <span class=\"kw-ttt\">mydriatiques</span><br><strong><span class=\"kw-bio\">CRP</span> franchement élevée :</strong> rechercher une affection <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-etio\">infectieuse</span> ou une <span class=\"kw-etio\">MICI</span> associée</p>","hospit":"<p><strong>Cadre :</strong> diagnostic et <span class=\"kw-def\">suivi</span> <span class=\"kw-ttt\">ambulatoires</span> (rhumatologue)<br><strong>Avis spécialisés :</strong> ophtalmologie si <span class=\"kw-etio\">uvéite</span>, gastro-entérologie si <span class=\"kw-etio\">MICI</span><br><strong><span class=\"kw-ttt\">Chirurgie</span> (rare) :</strong> <span class=\"kw-ttt\">prothèse articulaire</span> (coxite), <span class=\"kw-ttt\">ostéotomie rachidienne de correction</span> (cyphose dorsale majeure)<br><strong>Social :</strong> <span class=\"kw-ttt\">ALD 30</span> pour la SpA sévère</p>","redflags":"<ul><li><span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">VS</span> franchement élevées → affection <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-etio\">infectieuse</span> ou <span class=\"kw-etio\">MICI</span> associée à rechercher</li><li><span class=\"kw-radio\">Colonne bambou</span> cervicale → <span class=\"kw-alerte\">fractures transcorporéales/transdiscales instables</span>, <span class=\"kw-alerte\">risque de compression médullaire</span></li><li><span class=\"kw-etio\">Coxite</span> (atteinte coxo-fémorale) : facteur de mauvais <span class=\"kw-def\">pronostic</span> et source de handicap</li><li>Atteinte cardiaque : <span class=\"kw-etio\">insuffisance aortique</span>, <span class=\"kw-etio\">troubles de conduction</span> ; sur-risque CV (<span class=\"kw-alerte\">AVC</span>, <span class=\"kw-alerte\">IDM</span>)</li><li><span class=\"kw-clinique\">Diminution de l'ampliation thoracique</span> → <span class=\"kw-alerte\">syndrome restrictif</span> (ankylose costo-vertébrale)</li><li><span class=\"kw-etio\">Amylose AA</span> : rarissime mais peut être fatale</li><li>Facteurs de mauvais <span class=\"kw-def\">pronostic</span> : début <span class=\"kw-chiffre\">&lt; 16 ans</span>, <span class=\"kw-etio\">tabagisme actif</span>, <span class=\"kw-etio\">coxite</span>, <span class=\"kw-etio\">dactylite</span>, <span class=\"kw-radio\">syndesmophytes au diagnostic</span>, <span class=\"kw-clinique\">résistance aux AINS</span></li></ul>","principes":"<p><strong>Objectif :</strong> <span class=\"kw-def\">rémission</span> ou <span class=\"kw-def\">activité faible</span> de la maladie ; <span class=\"kw-ttt\">kinésithérapie</span> et <span class=\"kw-ttt\">activité physique</span> systématiques à tous <span class=\"kw-clinique\">les</span> stades</p><p><strong>1re intention — <span class=\"kw-ttt\">AINS</span> (pierre angulaire)</strong></p><p>Échec affirmé seulement après essai d'<span class=\"kw-chiffre\">≥2</span> <span class=\"kw-ttt\">AINS</span> successifs sur <span class=\"kw-chiffre\">4 semaines</span> au total</p><ul><li><span class=\"kw-ttt\">AINS</span> à dose optimale, prise le soir sous forme <span class=\"kw-ttt\">LP</span> (couvre la phase <span class=\"kw-etio\">inflammatoire</span> nocturne et matinale)</li><li>Efficaces sur la lombalgie <span class=\"kw-etio\">inflammatoire</span> dans <span class=\"kw-chiffre\">70%</span> des cas</li><li><span class=\"kw-ci\">Attention aux AINS si MICI associée</span> (risque d'ulcérations du grêle/côlon, hémorragie, perforation)</li><li><span class=\"kw-ci\">Diclofénac au long cours non admis</span> (risque cardiovasculaire)</li></ul><p><strong>Gestes locaux (si résistance au traitement général)</strong></p><ul><li>Arthrite : <span class=\"kw-ttt\">infiltration de corticoïdes</span>, <span class=\"kw-ttt\">synoviorthèse isotopique</span></li><li>Enthésopathie : <span class=\"kw-ttt\">infiltration cortisonique</span></li></ul><p><strong>Traitement de fond / DMARD (si échec <span class=\"kw-ttt\">AINS</span> + gestes locaux)</strong></p><p>Indication selon clinique, biologie/imagerie et <span class=\"kw-def\">score</span> d'activité (ASDAS, BASDAI)</p><ul><li>1re intention : <span class=\"kw-ttt\">biothérapie</span> <span class=\"kw-ttt\">anti-TNFα</span> (<span class=\"kw-ttt\">adalimumab</span>, <span class=\"kw-ttt\">étanercept</span>, golimumab, certolizumab pégol, <span class=\"kw-ttt\">infliximab</span>)</li><li>Alternative : <span class=\"kw-ttt\">biothérapie</span> <span class=\"kw-ttt\">anti-IL-17</span> (sécukinumab, ixékizumab)</li><li>Rhumatisme psoriasique uniquement : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">léflunomide</span>, <span class=\"kw-ttt\">aprémilast</span>, <span class=\"kw-ttt\">JAKi (tofacitinib)</span>, <span class=\"kw-ttt\">anti-IL-12/23 (ustékinumab)</span></li></ul><p><strong>Mesures non pharmacologiques (indispensables)</strong></p><ul><li><span class=\"kw-ttt\">Kinésithérapie</span> + <span class=\"kw-ttt\">activité physique régulière</span> : préviennent l'ankylose en mauvaise position</li><li><span class=\"kw-ttt\">Arrêt du tabac</span> indispensable (progression vers l'ankylose, moindre réponse aux anti-TNFα)</li><li>Contrôle des <span class=\"kw-ttt\">facteurs de risque cardiovasculaire</span></li><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">biomédicaments</span> n'ont pas d'effet sur l'ankylose et ne dispensent pas de la kinésithérapie</li></ul>","suivi":"<p><strong>Rythme :</strong> évaluation clinique tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span> selon l'<span class=\"kw-clinique\">évolution</span><br><strong>Activité :</strong> <span class=\"kw-clinique\">EVA</span>, scores <span class=\"kw-clinique\">BASDAI</span> et <span class=\"kw-clinique\">ASDAS</span> ; retentissement fonctionnel <span class=\"kw-clinique\">BASFI</span><br><strong>Biologie :</strong> <span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">VS</span> si <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> ; <span class=\"kw-bio\">créatinine</span> et <span class=\"kw-bio\">bilan hépatique</span> si <span class=\"kw-ttt\">AINS</span><br><strong>Imagerie :</strong> radiographies tous les <span class=\"kw-chiffre\">2-3 ans</span> dans les formes évolutives (rachis cervical de face, rachis lombaire face + profil, bassin)<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> l'<span class=\"kw-alerte\">ankylose constituée n'est pas récupérable</span> par la rééducation</p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-18-0.php","label":"COFER — cours spondyloarthrite"},{"href":"https://radiopaedia.org/articles/ankylosing-spondylitis-1","label":"Radiopaedia : Ankylosing spondylitis"},{"href":"https://radiopaedia.org/articles/sacroiliitis","label":"Radiopaedia : Sacroiliitis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"SpA active confirmée — Toujours associer kinésithérapie + activité physique + arrêt du tabac","detail":"<h4>CAT — Prise en charge thérapeutique de la spondyloarthrite — Objectif : <span class=\"kw-clinique\">rémission</span> ou activité faible de la maladie</h4>","branches":[{"to":"t-alerte","label":"Signe d'alerte (CRP franchement ↑, rachialgie aiguë sur colonne bambou)","color":"red"},{"to":"q-ains","label":"Pas de signe d'alerte → 1re intention AINS + kiné","color":"blue"}]},{"id":"t-alerte","kind":"terminal","label":"Rechercher une complication / affection associée","color":"red","detail":"<h4>Conduite</h4><ul><li>Élévation franche de la <span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">VS</span> → rechercher une affection <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-etio\">infectieuse</span> ou une <span class=\"kw-etio\">MICI</span></li><li>Rachialgie aiguë sur <span class=\"kw-radio\">colonne bambou</span> cervicale → suspecter une <span class=\"kw-alerte\">fracture transcorporéale/transdiscale instable</span></li><li><span class=\"kw-alerte\">Risque de compression médullaire</span> en cas de chute</li></ul>"},{"id":"q-ains","kind":"decision","label":"Réponse satisfaisante aux AINS ? — après essai d'≥2 AINS successifs sur 4 semaines au total","branches":[{"to":"t-controle","label":"Réponse satisfaisante","color":"green"},{"to":"q-pheno","label":"Échec (≥2 AINS / 4 sem) ± geste local inefficace","color":"amber"}]},{"id":"t-controle","kind":"terminal","label":"Poursuite AINS + kinésithérapie","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">AINS</span> à dose optimale, prise le soir (forme <span class=\"kw-ttt\">LP</span>)</li><li><span class=\"kw-ttt\">Kinésithérapie</span> + <span class=\"kw-ttt\">activité physique</span> poursuivies</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Évaluation clinique tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span> (EVA, BASDAI, ASDAS)</li><li><span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">VS</span> si <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span></li></ul>"},{"id":"q-pheno","kind":"decision","label":"Rhumatisme psoriasique ? — phénotype périphérique avec psoriasis","branches":[{"to":"t-biother","label":"Non (SpA axiale / autres)","color":"amber"},{"to":"t-pso","label":"Oui (rhumatisme psoriasique)","color":"amber"}]},{"id":"t-biother","kind":"terminal","label":"Traitement de fond (DMARD)","color":"amber","detail":"<h4>Traitement</h4><ul><li>1re intention : <span class=\"kw-ttt\">biothérapie</span> <span class=\"kw-ttt\">anti-TNFα</span> (<span class=\"kw-ttt\">adalimumab</span>, <span class=\"kw-ttt\">étanercept</span>, golimumab, certolizumab pégol, <span class=\"kw-ttt\">infliximab</span>)</li><li>Alternative : <span class=\"kw-ttt\">biothérapie</span> <span class=\"kw-ttt\">anti-IL-17</span> (sécukinumab, ixékizumab)</li></ul><h4>Conduite</h4><ul><li>Indication selon clinique, <span class=\"kw-bio\">CRP</span>/imagerie et <span class=\"kw-def\">score</span> d'activité (<span class=\"kw-clinique\">ASDAS</span>, <span class=\"kw-clinique\">BASDAI</span>)</li></ul>"},{"id":"t-pso","kind":"terminal","label":"Traitement de fond — rhumatisme psoriasique","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">anti-TNFα</span> ou <span class=\"kw-ttt\">anti-IL-17</span> (comme toute SpA)</li><li>Options spécifiques : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">léflunomide</span> (csDMARD)</li><li><span class=\"kw-ttt\">aprémilast</span> (PDE4i), <span class=\"kw-ttt\">JAKi (tofacitinib)</span>, <span class=\"kw-ttt\">anti-IL-12/23 (ustékinumab)</span></li></ul>"}]},"cards":[{"i":"552354d197ec","n":197,"o":"197-1","u":"Définition","t":"Connaître la définition et la description des spondyloarthrites","q":"Quelles sont les principales entités cliniques regroupées sous le terme de spondyloarthrites ?","a":"<ul><li>La <strong>spondyloarthrite ankylosante</strong> (SpA axiale radiographique)</li><li>Le <strong>rhumatisme psoriasique</strong></li><li>Les <strong>arthrites réactionnelles</strong></li><li>Les arthrites associées aux <strong>entérocolopathies inflammatoires</strong> (MICI)</li><li>Les formes juvéniles</li><li>Les SpA indifférenciées</li><li>Le <strong>syndrome SAPHO</strong> (selon certains, regroupant synovite, acné, pustulose, hyperostose, ostéite)</li></ul>"},{"i":"67e992b3ba56","n":197,"o":"197-1","u":"Définition","t":"Connaître la définition et la description des spondyloarthrites","q":"Quels sont les grands syndromes cliniques des spondyloarthrites ?","a":"<ul><li>Le <strong>syndrome pelvi-rachidien / axial</strong> : atteinte rachidienne et sacro-iliite.</li><li>Le <strong>syndrome enthésopathique</strong> : enthésites axiales ou périphériques.</li><li>Le <strong>syndrome articulaire périphérique</strong> : oligoarthrite et enthésites périphériques.</li><li>Le <strong>syndrome extra-articulaire</strong> : uvéite, psoriasis, MICI, atteintes cardiaques, infections urogénitales/digestives.</li></ul>"},{"i":"97101d785b0e","n":197,"o":"197-1","u":"Définition","t":"Connaître la définition et la description des spondyloarthrites","q":"Comment classifie-t-on les spondyloarthrites selon la nouvelle terminologie clinico-radiologique ?","a":"<ul><li>Les <strong>SpA axiales</strong> :<ul><li><strong>Radiographiques</strong> (spondyloarthrite ankylosante) : avec sacro-iliite radiographique.</li><li><strong>Non radiographiques</strong> : sans sacro-iliite radiographique.</li></ul></li><li>Les <strong>SpA périphériques articulaires</strong> : érosives ou non érosives.</li><li>Les <strong>SpA enthésiques</strong> (spondyloarthrites périphériques enthésiques).</li></ul>"},{"i":"d087e35c0c70","n":197,"o":"197-1","u":"Définition","t":"Connaître la définition et la description des spondyloarthrites","q":"Quelle est la définition des spondyloarthrites (SpA) ?","a":"<p>Les spondyloarthrites (SpA) sont des <strong>rhumatismes inflammatoires chroniques</strong> partageant des manifestations cliniques et un terrain génétique commun, notamment le <strong>gène HLA-B27</strong>.</p>"},{"i":"478881f3fec9","n":197,"o":"197-10","u":"Contenu multimédia","t":"Radiographie du rachis","q":"Quels clichés radiographiques du rachis sont à réaliser pour le diagnostic et le suivi d'une spondylarthrite inflammatoire ?","a":"<p>Il convient de réaliser des clichés du rachis cervical, thoracique et lombaire, toujours de <strong>face et de profil</strong>. Pour le rachis cervical, des clichés spécifiques (face bouche ouverte, profil et profil en flexion) sont également utiles.</p>"},{"i":"5cd9543ec262","n":197,"o":"197-10","u":"Contenu multimédia","t":"Radiographie du rachis","q":"Quelles sont les anomalies radiologiques précoces de la spondylarthrite inflammatoire au niveau de la charnière thoraco-lombaire, et comment évoluent-elles ?","a":"<p>Les anomalies radiologiques précoces sont :</p><ul><li>L'<strong>érosion inflammatoire de l'angle antérieur de la vertèbre</strong> (ou spondylite antérieure de Romanus).</li><li>Évolution vers la <strong>« mise au carré » de la vertèbre (squaring)</strong>.</li><li>Puis formation de <strong>syndesmophytes</strong>.</li><li>Dans les formes ankylosantes, on peut observer une <strong>ossification des ligaments intervertébraux</strong>, aboutissant à l'aspect classique de <strong>« colonne bambou »</strong> ou en <strong>« rail de chemin de fer »</strong> sur les clichés de face.</li></ul>"},{"i":"5f29445aed8d","n":197,"o":"197-10","u":"Contenu multimédia","t":"Radiographie du rachis","q":"Quelle est l'anomalie radiologique la plus spécifique de la spondylarthrite inflammatoire au niveau du rachis, et comment se caractérise-t-elle ?","a":"<p>L'anomalie radiologique la plus spécifique de la spondylarthrite inflammatoire est le <strong>syndesmophyte</strong>. Il se caractérise par une <strong>ossification fine et verticale de l'annulus fibrosus et des ligaments</strong>, pouvant être ascendante ou descendante, et pouvant fusionner deux vertèbres.</p>"},{"i":"be3b435b4e71","n":197,"o":"197-10","u":"Contenu multimédia","t":"Radiographie du rachis","q":"Comment différencier un syndesmophyte d'un ostéophyte sur une radiographie rachidienne ?","a":"<p>Un <strong>syndesmophyte</strong> est une ossification <strong>fine et verticale</strong>, spécifique d'une spondyloarthrite. Un <strong>ostéophyte</strong> est une excroissance osseuse <strong>grossière et horizontale</strong>, associée à l'arthrose, et s'accompagne souvent d'une sclérose et d'une dégénérescence discale.</p>"},{"i":"6efe468753bf","n":197,"o":"197-12","u":"Examens complémentaires","t":"Connaître l’utilisation rationnelle des examens biologiques et d’imagerie","q":"Quelle est la modalité d'imagerie de première intention pour le diagnostic d'une spondylarthrite inflammatoire, et quelles structures évalue-t-elle ?","a":"<p>La <strong>radiographie standard</strong> est l'imagerie de première intention. Elle évalue principalement :<ul><li>Les <strong>articulations sacro-iliaques</strong> pour rechercher une sacro-iliite.</li><li>Le <strong>rachis</strong> (rachis dorso-lombaire avec cliché de Sèze, rachis cervical avec profil, profil en flexion et face bouche ouverte) pour les syndesmophytes et l'ankylose.</li><li>Le <strong>bassin</strong> de face.</li><li>Les <strong>pieds</strong> de profil pour les épines calcanéennes.</li></ul></p>"},{"i":"7c7c692a53ab","n":197,"o":"197-12","u":"Examens complémentaires","t":"Connaître l’utilisation rationnelle des examens biologiques et d’imagerie","q":"Quelle est l'utilité clinique de la CRP et de la VS dans le bilan initial d'une spondylarthrite inflammatoire (SpA) ?","a":"<p>La <strong>CRP</strong> et la <strong>VS</strong> sont élevées chez environ <strong>60 %</strong> des patients atteints de SpA non traitée. Elles témoignent d'un syndrome inflammatoire, généralement plus modeste que dans la polyarthrite rhumatoïde. Une élévation importante doit faire rechercher une affection associée (tumorale, infectieuse, MICI).</p>"},{"i":"904d4dc31050","n":197,"o":"197-12","u":"Examens complémentaires","t":"Connaître l’utilisation rationnelle des examens biologiques et d’imagerie","q":"Quel est l'intérêt de l'IRM dans le diagnostic d'une spondylarthrite inflammatoire ?","a":"<p>L'<strong>IRM</strong> est utile pour le <strong>diagnostic précoce</strong> de la SpA, car elle peut détecter des remaniements inflammatoires précédant l'apparition des lésions radiographiques. Cependant, sa spécificité est imparfaite, et elle peut montrer des anomalies transitoires chez des sujets sains (obésité, âge, grossesse récente, sport intensif, arthrose). Elle n'a pas d'intérêt supplémentaire si une sacro-iliite est déjà visible en radiographie standard.</p>"},{"i":"e96a06a845f9","n":197,"o":"197-12","u":"Examens complémentaires","t":"Connaître l’utilisation rationnelle des examens biologiques et d’imagerie","q":"Quand le typage HLA-B27 est-il indiqué dans le diagnostic d'une spondylarthrite inflammatoire ?","a":"<p>Le typage <strong>HLA-B27</strong> n'est pas utile si la SpA est déjà certaine. Il est demandé uniquement en cas de doute diagnostique pour aider à appliquer les critères ASAS. Sa présence conforte le diagnostic sans l'affirmer (97 % des B27+ n'ont pas de SpA), et son absence ne l'écarte pas (10 % des SpA sont B27−).</p>"},{"i":"0e9d13b988bb","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Quelles sont les caractéristiques importantes de l'utilisation des AINS dans la spondylarthrite inflammatoire, notamment en cas d'échec initial ?","a":"<ul><li>Les AINS sont efficaces sur la lombalgie inflammatoire dans <strong>70%</strong> des cas, avec un délai d'action rapide.</li><li>Il est recommandé d'utiliser une <strong>dose optimale</strong>, parfois le soir sous forme LP (libération prolongée) pour couvrir l'inflammation nocturne/matinale.</li><li>En cas d'échec, il faut <strong>changer d'AINS</strong> après <strong>2 semaines</strong> d'essai, et essayer au moins <strong>2 AINS différents</strong> sur une période totale de <strong>4 semaines</strong> avant de conclure à l'échec de cette classe thérapeutique.</li><li>Une attention particulière doit être portée en cas de MICI associée, en raison du risque de complications digestives (ulcérations, hémorragie, perforation).</li></ul>"},{"i":"1ce508f1b2c2","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Comment évalue-t-on la réponse au traitement dans la spondylarthrite inflammatoire ?","a":"<p>La réponse au traitement est évaluée sur l'<strong>EVA</strong> (Échelle Visuelle Analogique), le <strong>syndrome inflammatoire</strong> (biologique) et les <strong>scores d'activité</strong> de la maladie tels que le <strong>BASDAI</strong> ou l'<strong>ASDAS</strong>.</p>"},{"i":"93a514421968","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Quel est l'objectif thérapeutique principal dans la prise en charge d'une spondylarthrite inflammatoire ?","a":"<p>L'objectif thérapeutique principal est d'atteindre la <strong>rémission</strong> de la maladie ou une <strong>activité faible</strong> de celle-ci.</p>"},{"i":"9da8e537a4f9","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Quels sont les traitements de première ligne pharmacologiques de la spondylarthrite active et leur place dans l'algorithme thérapeutique ?","a":"<p>Les traitements de première ligne pharmacologiques sont les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens), éventuellement associés à des infiltrations de corticoïdes. Ils constituent la pierre angulaire du traitement initial.</p>"},{"i":"c66f3c127296","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Quels sont les traitements de fond (DMARDs) utilisés en cas de réponse insuffisante aux AINS dans la spondylarthrite inflammatoire ?","a":"<ul><li>En première intention, des <strong>biothérapies anti-TNFα</strong> (adalimumab, étanercept, golimumab, certolizumab pegol, infliximab) sont utilisées, efficaces dans toutes les formes de SpA.</li><li>Selon le phénotype, d'autres biothérapies peuvent être employées : <strong>anti-IL-17</strong> (sécukinumab, ixékizumab, uniquement dans le rhumatisme psoriasique), <strong>anti-IL-12/IL-23</strong> (ustékinumab).</li><li>Des <strong>csDMARDs</strong> (méthotrexate, léflunomide) ou <strong>tsDMARDs</strong> (aprémilast, tofacitinib) peuvent également être utilisés pour certaines formes, notamment le rhumatisme psoriasique.</li></ul>"},{"i":"ea36d1d6bbdb","n":197,"o":"197-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge pharmacologique et non pharmacologique","q":"Quelles sont les principales approches non pharmacologiques indispensables dans la prise en charge de la spondylarthrite inflammatoire ?","a":"<p>Les approches non pharmacologiques <strong>indispensables</strong> sont l'<strong>activité physique régulière</strong> et la <strong>kinésithérapie</strong>. Elles visent à réduire le risque d'<strong>ankylose en mauvaise position</strong>. La kinésithérapie comprend l'autograndissement, les postures anti-cyphose, la mobilisation des hanches en extension et la rééducation respiratoire. L'<strong>arrêt du tabac</strong> est également crucial en raison de son impact sur la progression de l'ankylose et la réponse aux traitements.</p>"},{"i":"52146bc089b6","n":197,"o":"197-5","u":"Diagnostic positif","t":"Connaître les signes articulaires et périarticulaires","q":"Quelles articulations sont le plus souvent touchées dans le syndrome articulaire périphérique de la spondylarthrite inflammatoire ?","a":"<p>Le syndrome articulaire périphérique est une <strong>oligoarthrite</strong> touchant volontiers les <strong>grosses articulations des membres inférieurs</strong> dans l'ordre suivant : <strong>genou > cheville > hanche</strong>. Des arthrites des articulations interphalangiennes distales (IPD) et des <strong>dactylites</strong> (doigts ou orteils « en saucisse ») peuvent également être observées.</p>"},{"i":"5ce22eb52839","n":197,"o":"197-5","u":"Diagnostic positif","t":"Connaître les signes articulaires et périarticulaires","q":"Quelles sont les caractéristiques des douleurs sacro-iliaques (pygalgies/fessalgies) dans la spondylarthrite inflammatoire ?","a":"<p>Les douleurs sacro-iliaques se manifestent typiquement par un mode d'apparition <strong>brutal</strong>, une latéralité <strong>unilatérale, bilatérale ou à bascule</strong>, et un <strong>horaire inflammatoire</strong>. Elles peuvent irradier en dessous du pli fessier (<strong>sciatalgie tronquée</strong>) et ne présentent pas de caractère neurogène.</p>"},{"i":"ab92f5014e3a","n":197,"o":"197-5","u":"Diagnostic positif","t":"Connaître les signes articulaires et périarticulaires","q":"Comment évalue-t-on cliniquement une atteinte sacro-iliaque dans la spondylarthrite inflammatoire ?","a":"<p>On utilise le <strong>test de Patrick (FABER)</strong>, qui reproduit la douleur par flexion, abduction et rotation externe de la hanche. L'origine sacro-iliaque est confirmée si &ge; 3 manœuvres de cisaillement sont positives, maintenues &ge; 20 secondes chacune (FABER, écartement des sacro-iliaques, rapprochement des ailes iliaques, signe du trépied, cisaillement vertical/horizontal comme le <strong>test de Gaenslen</strong>).</p>"},{"i":"b96785c110d6","n":197,"o":"197-5","u":"Diagnostic positif","t":"Connaître les signes articulaires et périarticulaires","q":"Comment se manifeste cliniquement le syndrome pelvi-rachidien (axial) de la spondylarthrite inflammatoire ?","a":"<p>Il se caractérise par des <strong>dorso-lombalgies inflammatoires</strong> (évoluant depuis &ge; 3 mois), une raideur axiale avec diminution de l'<strong>indice de Schöber</strong>, augmentation de la <strong>distance main-sol</strong> et une perte de l'inflexion latérale lombaire. Des atteintes plus évoluées incluent la disparition de la lordose lombaire et l'exagération de la cyphose dorsale.</p>"},{"i":"bdf96e696516","n":197,"o":"197-5","u":"Diagnostic positif","t":"Connaître les signes articulaires et périarticulaires","q":"Quelles sont les caractéristiques cliniques des enthésopathies périphériques dans la spondylarthrite inflammatoire ?","a":"<p>Les enthésopathies périphériques se manifestent le plus souvent par une <strong>talalgie calcanéenne</strong> (plantar inférieure ou postérieure), terrain très évocateur chez le sujet jeune, d'horaire <strong>inflammatoire</strong> (douleur au lever et s'améliorant dans la journée). Des <strong>dactylites</strong> et des atteintes de la paroi thoracique antérieure (articulations sterno-claviculaires, manubrio-sternale, chondro-sternales) peuvent aussi être présentes.</p>"},{"i":"1bc3e09973b2","n":197,"o":"197-9","u":"Contenu multimédia","t":"Photographie d’une dactylite","q":"Quels sont les substratums lésionnels de la dactylite ?","a":"<ul><li>Une <strong>enthésopathie inflammatoire distale</strong>.</li><li>Une <strong>ténosynovite</strong>.</li><li>Une <strong>arthrite</strong>, le plus souvent <strong>tripolaire</strong> (atteignant la métacarpo/métatarso-phalangienne, l'interphalangienne proximale et l'interphalangienne distale).</li></ul>"},{"i":"3fc8b8d19a66","n":197,"o":"197-9","u":"Contenu multimédia","t":"Photographie d’une dactylite","q":"Quelles sont les principales étiologies de la dactylite ?","a":"<ul><li>Le <strong>rhumatisme psoriasique</strong>, où la dactylite est un signe clinique majeur retenu dans les critères CASPAR.</li><li>Les <strong>spondylarthrites axiales</strong>.</li><li>Plus rarement, l'arthrite, la goutte ou la sarcoïdose.</li></ul>"},{"i":"794f10f55687","n":197,"o":"197-9","u":"Contenu multimédia","t":"Photographie d’une dactylite","q":"Quel est le principal diagnostic différentiel à évoquer face à une dactylite du 1er rayon (gros orteil ou pouce) ?","a":"<p>Au niveau du 1<sup>er</sup> rayon, la dactylite ne doit pas être confondue avec une atteinte exclusive de l'articulation métatarso-phalangienne, qui est évocatrice d'une <strong>crise de goutte</strong>.</p>"},{"i":"fabcbd9b3122","n":197,"o":"197-9","u":"Contenu multimédia","t":"Photographie d’une dactylite","q":"Quelle est la définition clinique d'une dactylite lors d'une spondylarthrite inflammatoire ?","a":"<p>La dactylite est une atteinte inflammatoire de l'ensemble d'un doigt ou d'un orteil, réalisant un aspect caractéristique « <strong>en saucisse</strong> » avec une <strong>tuméfaction globale</strong> et une <strong>rougeur</strong>.</p>"}]};